"""Manual sequential source programs combining references and owned resources."""
CASES=[
('file-snapshot','''server fn main()->i64!{state,fs}{let value:cell<str>=cell_new(unwrap(file_read_text("input")));let old:str=cell_read(value);assert(unwrap(file_write_text("out","changed")));cell_write(value,unwrap(file_read_text("out")));cell_collect();assert(old=="abcdef"&&cell_read(value)=="changed");return 42;}''',False,None),
('file-closure','''server fn main()->i64!{state,fs}{let file:file=unwrap(file_open_read("input"));let total:cell<i64>=cell_new(0);let next:server fn()->i64!{state,fs}=server fn()->i64!{state,fs}{cell_write(total,cell_read(total)+len(unwrap(file_read(file,2))));return cell_read(total);};assert(next()==2);cell_collect();assert(next()==4);assert(file_close(file));return 42;}''',False,None),
('file-source-loop','''server fn main()->i64!{state,fs}{let total:cell<i64>=cell_new(0);var i:i64=0;while i<80{try{let f:file=unwrap(file_open_read("input"));cell_write(total,cell_read(total)+len(unwrap(file_read(f,1))));throw("DROP","file");}catch(code,message){assert(code=="DROP");cell_collect();}i=i+1;}assert(cell_read(total)==80);return 42;}''',False,None),
('file-typed-error','''struct Packet{file:file;value:cell<i64>;}server fn leaf(value:cell<i64>)->unit!{fs,throw}{throw(Packet(unwrap(file_open_read("input")),value));}server fn main()->i64!{state,fs,throw}{let value:cell<i64>=cell_new(0);try{leaf(value);}catch(packet:Packet){cell_collect();assert(packet.value==value);cell_write(packet.value,len(unwrap(file_read(packet.file,6))));assert(file_close(packet.file));}assert(cell_read(value)==6);return 42;}''',False,None),
('file-result-finally','''server fn early(value:cell<i64>)->result<i64>!{state,fs}{let f:file=unwrap(file_open_read("input"));try{let n:i64=err<i64>("EARLY","exit")?;return ok(n);}finally{cell_write(value,42);}}server fn main()->i64!{state,fs}{let value:cell<i64>=cell_new(0);let result:result<i64>=early(value);assert(!is_ok(result)&&error_code(result)=="EARLY");cell_collect();assert(cell_read(value)==42);return 42;}''',False,None),
('file-fatal','''server fn main()->i64!{state,fs}{let value:cell<i64>=cell_new(0);try{let f:file=unwrap(file_open_read("input"));cell_write(value,42);assert(false);}finally{assert(unwrap(file_write_text("wrong","finalizer")));}return 0;}''',False,'E_ASSERT'),
('file-hidden-owned-cell','''server fn main()->i64!{state,fs}{let f:file=unwrap(file_open_read("input"));let callback:server fn()->bool!{fs}=server fn()->bool!{fs}{return file_is_open(f);};let stored:cell<server fn()->bool!{fs}>=cell_new(callback);cell_collect();assert(cell_read(stored)());assert(file_close(f));assert(!cell_read(stored)());return 42;}''',False,None),
('resource-state','''server fn main()->i64!{state,ffi}{let owner:Counter=create(41);let value:cell<i64>=cell_new(read(owner));cell_write(value,add(cell_read(value)));cell_collect();assert(cell_read(value)==42);assert(resource_close(owner));return 42;}''',True,None),
('resource-source-loop','''server fn main()->i64!{state,ffi}{let value:cell<i64>=cell_new(0);var i:i64=0;while i<80{try{let owner:Counter=create(i);cell_write(value,read(owner));throw("DROP","owner");}catch(code,message){assert(code=="DROP");cell_collect();}i=i+1;}assert(cell_read(value)==79);return 42;}''',True,None),
('resource-typed-error','''struct Packet{owner:Counter;value:cell<i64>;}server fn leaf(value:cell<i64>)->unit!{ffi,throw}{throw(Packet(create(42),value));}server fn main()->i64!{state,ffi,throw}{let value:cell<i64>=cell_new(0);try{leaf(value);}catch(packet:Packet){cell_collect();assert(packet.value==value);cell_write(packet.value,read(packet.owner));assert(resource_close(packet.owner));}assert(cell_read(value)==42);return 42;}''',True,None),
('resource-result-data','''server fn main()->i64!{state,ffi}{let value:cell<str>=cell_new("");try{let r:result<i64>=ordinary();throw(error_code(r),error_message(r));}catch(code,message){cell_write(value,message);assert(code=="E_LIMIT"&&len(cell_read(value))==3);}return 42;}''',True,None),
('resource-fatal','''server fn main()->i64!{state,ffi}{let value:cell<i64>=cell_new(0);try{let owner:Counter=create(42);cell_write(value,read(owner));return bad();}finally{cell_write(value,0);}}''',True,'E_FFI_TYPE'),
('resource-hidden-owned-cell','''server fn main()->i64!{state,ffi}{let owner:Counter=create(42);let callback:server fn()->i64!{ffi}=server fn()->i64!{ffi}{return read(owner);};let stored:cell<server fn()->i64!{ffi}>=cell_new(callback);cell_collect();assert(cell_read(stored)()==42);assert(resource_close(owner));cell_collect();return 42;}''',True,None),
('mixed-file-resource','''server fn leaf(value:cell<i64>)->unit!{state,fs,ffi,throw}{let f:file=unwrap(file_open_read("input"));let owner:Counter=create(41);cell_write(value,add(read(owner)));assert(len(unwrap(file_read(f,1)))==1);throw("MIXED","settled");}server fn main()->i64!{state,fs,ffi}{let value:cell<i64>=cell_new(0);try{leaf(value);}catch(code,message){cell_collect();assert(code=="MIXED"&&cell_read(value)==42);}return 42;}''',True,None),
('mixed-uncaught-typed','''struct Packet{owner:Counter;file:file;value:cell<i64>;}server fn main()->i64!{state,fs,ffi,throw}{let value:cell<i64>=cell_new(42);throw(Packet(create(42),unwrap(file_open_read("input")),value));}''',True,'E_SOURCE_EXCEPTION'),
('file-cell-snapshots','''server fn main()->i64!{state,fs}{let value:cell<file>=cell_new(unwrap(file_open_read("input")));let old:file=cell_read(value);cell_write(value,unwrap(file_open_read("input")));cell_collect();assert(unwrap(file_read(old,2))==utf8_bytes("ab"));assert(unwrap(file_read(cell_read(value),1))==utf8_bytes("a"));assert(file_close(old));assert(file_is_open(cell_read(value)));assert(file_close(cell_read(value)));cell_write(value,old);cell_collect();assert(!file_is_open(cell_read(value)));return 42;}''',False,None),
('file-cell-cycle','''server fn cycle()->unit!{state,fs}{let f:file=unwrap(file_open_read("input"));let value:cell<list<server fn()->bool!{state,fs}>>=cell_new<list<server fn()->bool!{state,fs}>>([]);let callback:server fn()->bool!{state,fs}=server fn()->bool!{state,fs}{assert(len(cell_read(value))==1);return file_is_open(f);};cell_write(value,[callback]);assert(cell_read(value)[0]());}server fn main()->i64!{state,fs}{var i:i64=0;while i<80{cycle();cell_collect();i=i+1;}return 42;}''',False,None),
('resource-cell-cycle','''server fn cycle()->unit!{state,ffi}{let owner:Counter=create(42);let value:cell<list<server fn()->i64!{state,ffi}>>=cell_new<list<server fn()->i64!{state,ffi}>>([]);let callback:server fn()->i64!{state,ffi}=server fn()->i64!{state,ffi}{assert(len(cell_read(value))==1);return read(owner);};cell_write(value,[callback]);assert(cell_read(value)[0]()==42);}server fn main()->i64!{state,ffi}{var i:i64=0;while i<80{cycle();cell_collect();i=i+1;}return 42;}''',True,None),
('mixed-owned-cell','''struct Session{owner:Counter;file:file;}server fn make(value:i64)->cell<Session>!{state,fs,ffi}{return cell_new(Session(create(value),unwrap(file_open_read("input"))));}server fn main()->i64!{state,fs,ffi}{let session:cell<Session>=make(41);let old:Session=cell_read(session);cell_write(session,Session(create(42),unwrap(file_open_read("input"))));cell_collect();assert(read(old.owner)==41&&read(cell_read(session).owner)==42);assert(unwrap(file_read(old.file,2))==utf8_bytes("ab"));assert(unwrap(file_read(cell_read(session).file,1))==utf8_bytes("a"));assert(resource_close(old.owner));assert(file_close(old.file));return 42;}''',True,None),
('owned-cell-typed-error','''struct Session{owner:Counter;file:file;}server fn leaf()->unit!{state,fs,ffi,throw}{throw(cell_new(Session(create(42),unwrap(file_open_read("input")))));}server fn main()->i64!{state,fs,ffi,throw}{try{leaf();}catch(value:cell<Session>){cell_collect();assert(read(cell_read(value).owner)==42);assert(len(unwrap(file_read(cell_read(value).file,6)))==6);}return 42;}''',True,None),
('owned-cell-uncaught','''struct Session{owner:Counter;file:file;}server fn main()->i64!{state,fs,ffi,throw}{throw(cell_new(Session(create(42),unwrap(file_open_read("input")))));}''',True,'E_SOURCE_EXCEPTION'),
('owned-cell-fatal','''struct Session{owner:Counter;file:file;}server fn main()->i64!{state,fs,ffi}{let value:cell<Session>=cell_new(Session(create(42),unwrap(file_open_read("input"))));try{cell_collect();assert(read(cell_read(value).owner)==42);assert(false);}finally{assert(unwrap(file_write_text("wrong","finalizer")));}return 0;}''',True,'E_ASSERT'),
]
